import java.util.*;

class Person {
    String name;
    int age;
    boolean active;
    List<String> hobbies;

    // Constructor
    public Person(String name, int age, boolean active, List<String> hobbies) {
        this.name = name;
        this.age = age;
        this.active = active;
        this.hobbies = hobbies;
    }

    // Method to generate random string
    public static String randomString(int length) {
        String chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
        StringBuilder sb = new StringBuilder();
        Random random = new Random();

        for (int i = 0; i < length; i++) {
            sb.append(chars.charAt(random.nextInt(chars.length())));
        }
        return sb.toString();
    }

    // Generate random Person
    public static Person generateRandomPerson() {
        Random random = new Random();

        String name = randomString(10);
        int age = random.nextInt(100) + 1;
        boolean active = random.nextBoolean();

        int hobbyCount = random.nextInt(5) + 1;
        List<String> hobbies = new ArrayList<>();

        for (int i = 0; i < hobbyCount; i++) {
            hobbies.add(randomString(8));
        }

        return new Person(name, age, active, hobbies);
    }

    public static void main(String[] args) {
        List<Person> persons = new ArrayList<>();

        for (int i = 0; i < 1_000_000; i++) {
            persons.add(generateRandomPerson());
        }

        System.out.println("Generated persons: " + persons.size());
    }
}

