            persons.add(Person.generateRandomPerson());
        }

        // Protobuf Serialization
        PersonListProto.PersonList.Builder personListBuilder = PersonListProto.PersonList.newBuilder();

        for (Person person : persons) {
            PersonListProto.Person.Builder personBuilder = PersonListProto.Person.newBuilder();

            personBuilder.setName(person.name);
            personBuilder.setId(person.age);
            personBuilder.setActive(person.active);
            personBuilder.addAllHobbies(person.hobbies);

            personListBuilder.addPeople(personBuilder);
        }

        byte[] serializedProto = personListBuilder.build().toByteArray();

        // Protobuf Deserialization
        PersonListProto.PersonList deserializedProto =
                PersonListProto.PersonList.parseFrom(serializedProto);

        System.out.println("Deserialized count: " + deserializedProto.getPeopleCount());
    }
}

